import sys

def max_balanced_team(n, skills):
    skills.sort()
    max_team = 1
    current_team = 1

    for i in range(1, n):
        if skills[i] - skills[i-1] <= 5:
            current_team += 1
        else:
            max_team = max(max_team, current_team)
            current_team = 1

    return max(max_team, current_team)

def main():
    n = int(sys.stdin.readline().strip())
    skills = list(map(int, sys.stdin.readline().split()))

    result = max_balanced_team(n, skills)
    print(result)

if __name__ == "__main__":
    main()
